insert into public.companies (id, slug, name, logo_url, website, overview, mission, highlights, products, culture, benefits, benefits_scope, benefits_note, locations, locations_note, hiring_process, hiring_note, links, source, created_at, updated_at) values
  ('56bdf318-ed70-5cd7-bd73-762c04d76a9c', 'encord', 'Encord', '/logos/encord.svg', 'https://encord.com/', 'Encord builds the data development platform AI teams use to curate, annotate and evaluate multimodal training data, from images and video to documents and 3D sensor data.', 'AI alignment starts with Encord: the quality of AI is only as good as the data behind it. Encord builds the infrastructure to build, curate and validate training data, helping the world''s best AI teams move faster, label smarter and ship models that work in production, from autonomous vehicles to surgical robotics.', '[{"title": "300+", "description": "leading AI teams build with Encord, including Woven by Toyota, AXA, UiPath and Zipline"}, {"title": "$110M", "description": "total funding raised, from investors including Wellington Management, Y Combinator, CRV and N47"}, {"title": "45+", "description": "nationalities represented on the team"}]'::jsonb, '[{"title": "Label and annotate", "description": "Video, LiDAR, audio, text and sensor-fusion annotation in one workflow, with label lineage and quality controls built in for production scale."}, {"title": "Curate and collect", "description": "Collect data from dedicated facilities or a fleet, then use embedding-based search and model-in-the-loop curation to find rare edge cases and close distribution gaps."}, {"title": "Align and evaluate", "description": "RLHF, rubric-based evaluation and pairwise comparison for models in production, to find where AI fails and route it back into training."}, {"title": "Data-as-a-Service", "description": "Expert annotators, domain specialists and managed data collection, including teleoperation facilities for physical AI, integrated with the platform."}]'::jsonb, '[{"title": "High agency", "description": "You see something broken, you fix it or find the person who can. Encord celebrates the people who solve 90% of a problem before anyone asks."}, {"title": "Builds with care and urgency", "description": "Encord bear-hugs the customer. Former founders and people from fast-moving, high-stakes environments thrive here."}, {"title": "Self-aware and hungry", "description": "The team stays warm, self-aware and genuinely hungry. People elevate their peers, and ego doesn''t last long."}, {"title": "Invents in real time", "description": "The team moves toward ambiguity: pragmatic, resourceful and energised by the fact that there''s no playbook."}]'::jsonb, '["Equity in a hyper-growth startup", "25 days paid time off", "Private health insurance", "Annual learning and development stipend", "Monthly team events and bi-annual offsites", "Team lunch twice a week", "Visa sponsorship, considered case by case for the role, level and location", "Payroll giving scheme", "Cycle to work scheme", "Home and tech scheme", "A strong in-person culture"]'::jsonb, 'UK employees', 'These are the benefits Encord lists for UK employees. Benefits in the US differ; your recruiter can walk you through the package for your location.', '["London", "San Francisco", "New York"]'::jsonb, 'Encord describes a strong in-person culture. Each job posting lists its own location and work arrangement.', '["Recruiter screen", "Hiring manager conversation", "Skills-based interview or take-home", "Final panel"]'::jsonb, 'The process varies by role and team, and is usually four or five stages in total. Your recruiter walks you through the specific steps at the start, so there are no surprises.', '[{"label": "Encord website", "url": "https://encord.com/"}, {"label": "Explore the product", "url": "https://encord.com/explore-product/"}, {"label": "Careers and open roles", "url": "https://encord.com/careers/"}, {"label": "Encord blog", "url": "https://encord.com/blog/"}, {"label": "Trust center", "url": "https://trust.encord.com/"}]'::jsonb, 'From encord.com, October 2026.', now() - interval '576000 minutes', now() - interval '576000 minutes'),
  ('37d47137-f122-51f7-931f-432239fee7e1', 'nova-ai', 'Nova AI', '/logos/nova-ai.svg', 'https://nova-ai.example/', 'Nova AI builds speech and language models that let customer support teams answer people in more than 40 languages, in real time.', 'Make every conversation understood: an answer in your own language, without the wait.', '[{"title": "40+", "description": "languages supported in production"}, {"title": "120", "description": "people across Berlin and Lisbon"}, {"title": "$62M", "description": "raised to date, most recently a Series B led by Northlight Ventures"}]'::jsonb, '[{"title": "Nova Voice", "description": "Real-time speech recognition and synthesis, tuned for contact centres and noisy lines."}, {"title": "Nova Translate", "description": "Streaming translation between 40+ languages, with glossaries for each customer''s domain."}, {"title": "Nova Evaluate", "description": "An evaluation suite that checks model answers for accuracy, tone and policy compliance."}]'::jsonb, '[{"title": "Customers first", "description": "Every team spends time on real support calls, so decisions start from what customers hear."}, {"title": "Ship small, ship often", "description": "Small releases, measured carefully, beat big launches."}, {"title": "Say it plainly", "description": "Clear writing and direct feedback, given kindly."}, {"title": "Grow together", "description": "Senior people mentor, and everyone gets time to learn."}]'::jsonb, '["30 days paid holiday", "Hybrid working, two office days a week", "€2,000 annual learning budget", "Mental health support through a wellbeing platform", "Relocation support to Berlin or Lisbon", "Company-paid public transport ticket"]'::jsonb, 'all employees', 'Benefits are the same in Berlin and Lisbon. Your recruiter can share the details for your contract.', '["Berlin", "Lisbon"]'::jsonb, 'Most teams work hybrid, with two days a week in the office.', '["Recruiter screen", "Technical interview", "Team conversation", "Founder chat"]'::jsonb, 'Most processes take three to four weeks, and your recruiter shares feedback after every stage.', '[{"label": "Nova AI website", "url": "https://nova-ai.example/"}, {"label": "Engineering blog", "url": "https://nova-ai.example/blog/"}]'::jsonb, 'Fictional demo employer in TalentBridge''s seed data.', now() - interval '288000 minutes', now() - interval '288000 minutes'),
  ('4f84aa60-f014-585d-bea5-220227aa12fc', 'harbor-robotics', 'Harbor Robotics', '/logos/harbor-robotics.svg', 'https://harbor-robotics.example/', 'Harbor Robotics builds autonomous straddle carriers and the fleet software that runs them, so container terminals can move cargo safely around the clock.', 'Make ports safer and cleaner by automating the heaviest, most repetitive work on the quay.', '[{"title": "14", "description": "container terminals running Harbor fleets"}, {"title": "2M+", "description": "containers moved autonomously"}, {"title": "85", "description": "people across Rotterdam and Hamburg"}]'::jsonb, '[{"title": "Harbor Carrier", "description": "An electric, autonomous straddle carrier that lifts, moves and stacks containers."}, {"title": "Fleet OS", "description": "Plans, routes and monitors a terminal''s whole autonomous fleet in real time."}, {"title": "Harbor Twin", "description": "A simulation of each terminal, used to test every software release before it ships."}]'::jsonb, '[{"title": "Safety first", "description": "Every change is proven in simulation before it reaches a real carrier."}, {"title": "Own the outcome", "description": "Teams run what they build, from the design review to the night shift on the quay."}, {"title": "Stay curious", "description": "Hard problems are shared openly, and anyone can ask why."}]'::jsonb, '["28 days paid holiday", "Flexible hours around a 10:00 to 15:00 core", "Pension contribution of 8% of salary", "€1,500 annual learning budget", "Bike lease scheme"]'::jsonb, 'employees in the Netherlands and Germany', 'Benefits follow the local contract in each country. Your recruiter can share the details for yours.', '["Rotterdam", "Hamburg"]'::jsonb, 'Engineers work on site three days a week, with regular visits to customer terminals.', '["Recruiter call", "Technical screen", "Systems interview", "Terminal visit and team lunch"]'::jsonb, 'Most processes take about three weeks, and your recruiter shares feedback after each stage.', '[{"label": "Harbor Robotics website", "url": "https://harbor-robotics.example/"}, {"label": "Engineering at Harbor", "url": "https://harbor-robotics.example/engineering/"}]'::jsonb, 'Fictional demo employer in TalentBridge''s seed data.', now() - interval '216000 minutes', now() - interval '216000 minutes'),
  ('291d727f-4feb-5871-9947-f601ee881c23', 'openai', 'OpenAI', null, 'https://openai.com/', 'OpenAI is an AI research and deployment company.', 'To ensure that artificial general intelligence benefits all of humanity.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '', '', '[]'::jsonb, '', '[]'::jsonb, '', '[{"label": "OpenAI website", "url": "https://openai.com/"}, {"label": "About OpenAI", "url": "https://openai.com/about/"}]'::jsonb, 'Demo employer in TalentBridge''s seed data, described in OpenAI''s own words from openai.com/about.', now() - interval '144000 minutes', now() - interval '144000 minutes'),
  ('2578bd3e-85f0-5b9b-adcf-1b2a5b2a4787', 'anthropic', 'Anthropic', null, 'https://www.anthropic.com/', 'Anthropic is an AI safety and research company that''s working to build reliable, interpretable, and steerable AI systems.', '', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '', '', '[]'::jsonb, '', '[]'::jsonb, '', '[{"label": "Anthropic website", "url": "https://www.anthropic.com/"}, {"label": "About Anthropic", "url": "https://www.anthropic.com/company"}]'::jsonb, 'Demo employer in TalentBridge''s seed data, described in Anthropic''s own words from anthropic.com/company.', now() - interval '144000 minutes', now() - interval '144000 minutes'),
  ('d2e9ad14-5e68-5a16-8153-b35fcc68e531', 'google', 'Google', null, 'https://about.google/', 'Google''s mission is to organize the world''s information and make it universally accessible and useful.', 'To organize the world''s information and make it universally accessible and useful.', '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '', '', '[]'::jsonb, '', '[]'::jsonb, '', '[{"label": "About Google", "url": "https://about.google/"}, {"label": "Google company info", "url": "https://about.google/company-info/"}]'::jsonb, 'Demo employer in TalentBridge''s seed data, described in Google''s own words from about.google.', now() - interval '144000 minutes', now() - interval '144000 minutes');
