  ('e358967f-40d4-5c4b-9a96-fc319ad1a82b', '0636b5c5-72e9-5b7f-a280-d1c7b33e78a1', 'Technical screen', 'video', date_trunc('day', now()) + interval '3 days 16 hours 0 minutes', 45, 'scheduled', 'https://meet.example.com/james-park', null, '["Tom Reid"]'::jsonb, null, now() - interval '4320 minutes', now() - interval '4320 minutes'),
  ('18ec1ca1-37f9-5811-9ca2-acea4fc83fd1', 'cef4d65a-28c9-5ead-8df0-9324ef78b2da', 'Research deep dive', 'video', date_trunc('day', now()) + interval '4 days 13 hours 0 minutes', 60, 'scheduled', 'https://meet.example.com/omar-haddad', null, '["Ana Silva"]'::jsonb, null, now() - interval '4320 minutes', now() - interval '4320 minutes'),
  ('040645e2-4e93-512d-a4e0-283b221c06b5', '6ff4641e-bb28-522f-9709-10cd715cb709', 'Frontend pairing session', 'video', date_trunc('day', now()) + interval '5 days 10 hours 0 minutes', 90, 'scheduled', 'https://meet.example.com/ben-carter', null, '["Ian Park", "Leo Brandt"]'::jsonb, now() - interval '15000 minutes', now() - interval '4320 minutes', now() - interval '4320 minutes'),
  ('eaa47009-ecde-56bc-9f2d-cce7b879ce5a', '81164425-2db8-5c8e-ba34-0a3f1b246e9b', 'Infrastructure interview', 'video', date_trunc('day', now()) + interval '-3 days 15 hours 0 minutes', 60, 'completed', null, null, '["Ian Park"]'::jsonb, now() - interval '7200 minutes', now() - interval '14400 minutes', now() - interval '4320 minutes'),
  ('f0fbe0ed-c144-5bc6-af23-6e74bae95fe5', '9ba87e3b-2ac4-5432-a823-4e50d03eabc4', 'Portfolio review', 'video', date_trunc('day', now()) + interval '-4 days 11 hours 0 minutes', 45, 'completed', null, 'Strong design systems thinking and clear rationale for component decisions. Prototyping was fast and polished. Recommend the design interview.', '["Maya Okafor"]'::jsonb, now() - interval '8640 minutes', now() - interval '15840 minutes', now() - interval '5760 minutes'),
  ('f15f9496-a6ff-51d3-896d-5eb4c0156866', 'fbde98a6-db26-535d-b40c-b159633f409c', 'Final interview', 'onsite', date_trunc('day', now()) + interval '-5 days 14 hours 0 minutes', 60, 'completed', null, 'Excellent depth on experimentation and causal inference, and explained trade-offs clearly to a non-technical panel.', '["Ana Silva", "Tom Reid"]'::jsonb, now() - interval '10080 minutes', now() - interval '17280 minutes', now() - interval '7200 minutes'),
  ('f17a3e64-a3d2-5d60-b9f5-cc5f2ba513b2', 'ab2b5fcd-3419-5f4f-9403-5cdeb8d34fdb', 'Recruiter screen', 'phone', date_trunc('day', now()) + interval '-10 days 10 hours 0 minutes', 30, 'completed', null, 'Clear product thinking on ML tooling and a strong B2B SaaS background. Motivated by the data-curation problem space.', '["Alex Chen"]'::jsonb, now() - interval '17280 minutes', now() - interval '24480 minutes', now() - interval '14400 minutes'),
  ('80eceb64-b425-5afe-a30a-a34be782a29d', '57ad530b-ba59-5753-980c-0655b3f0ffe0', 'Systems design interview', 'video', date_trunc('day', now()) + interval '2 days 15 hours 0 minutes', 60, 'scheduled', 'https://meet.example.com/rosa-navarro', null, '["Ian Park"]'::jsonb, null, now() - interval '4320 minutes', now() - interval '4320 minutes'),
  ('876c86e0-b581-596f-beef-95b822c6cb5e', '57ad530b-ba59-5753-980c-0655b3f0ffe0', 'Recruiter screen', 'phone', date_trunc('day', now()) + interval '-6 days 11 hours 0 minutes', 30, 'completed', null, 'Strong distributed systems background; check depth on Kubernetes operations.', '["Alex Chen"]'::jsonb, now() - interval '11520 minutes', now() - interval '18720 minutes', now() - interval '8640 minutes'),
  ('113bf2f6-1d71-5b45-9526-ad43353d1d63', '7b6a49e9-59bc-53f1-bf85-d1b3e3160201', 'Technical interview', 'video', date_trunc('day', now()) + interval '4 days 13 hours 0 minutes', 60, 'scheduled', 'https://meet.example.com/rosa-navarro-nova-ai', null, '["Lena Vogel", "Tariq Aziz"]'::jsonb, null, now() - interval '4320 minutes', now() - interval '4320 minutes'),
  ('b4e2e1ad-e091-5398-a5dc-404eb87f0930', '7b6a49e9-59bc-53f1-bf85-d1b3e3160201', 'Recruiter screen', 'phone', date_trunc('day', now()) + interval '-9 days 9 hours 30 minutes', 30, 'completed', null, 'Strong on LLM evaluation; probe system design depth in the technical round.', '["Mira Hoffmann"]'::jsonb, now() - interval '15840 minutes', now() - interval '23040 minutes', now() - interval '12960 minutes'),
  ('a78c454f-3a61-546a-9f06-a8d8063386d5', '66ce4a5a-eb68-5fac-9ef2-3d6737a82db4', 'Design exercise', 'video', date_trunc('day', now()) + interval '3 days 16 hours 0 minutes', 60, 'scheduled', 'https://meet.example.com/sophia-martinez-google', null, '["Aiko Mori"]'::jsonb, null, now() - interval '4320 minutes', now() - interval '4320 minutes');
insert into public.messages (id, application_id, sender_type, content, created_at, read_at) values
  ('e2dbef3e-363d-57e0-8b6a-db6e9e73372c', '9ba87e3b-2ac4-5432-a823-4e50d03eabc4', 'recruiter', 'Hi Sophia, thanks again for the portfolio review. The team loved your design systems work. We''d like to invite you to a design interview with Maya and Leo. I''ll send a few time options shortly.', now() - interval '7300 minutes', now() - interval '7100 minutes'),
  ('215d51dd-1885-58ee-94a8-ac47df7c2a2e', '9ba87e3b-2ac4-5432-a823-4e50d03eabc4', 'candidate', 'That''s great news, thank you! Any of those slots should work for me.', now() - interval '7100 minutes', now() - interval '7070 minutes'),
  ('53ca1990-5d9c-576e-a6fe-ba04a6f68813', '9ba87e3b-2ac4-5432-a823-4e50d03eabc4', 'recruiter', 'Your design interview is booked. I''ve also added prep materials to your candidate portal, including an outline of the design exercise.', now() - interval '2900 minutes', now() - interval '120 minutes'),
  ('b6665711-9be1-50e8-8fdc-2d47748bc420', '9ba87e3b-2ac4-5432-a823-4e50d03eabc4', 'candidate', 'Thanks Alex! Just confirmed for tomorrow at 10. Is there anything specific I should prepare for the design exercise?', now() - interval '120 minutes', null),
  ('ef826048-3981-588c-934b-075ec6123003', '0636b5c5-72e9-5b7f-a280-d1c7b33e78a1', 'recruiter', 'Hi James, thanks for sending over your take-home. Tom would love to do a technical screen. Would early next week work?', now() - interval '2000 minutes', now() - interval '300 minutes'),
  ('161712b2-f210-55a3-a1a2-902c44fdb18b', '0636b5c5-72e9-5b7f-a280-d1c7b33e78a1', 'candidate', 'Hi Alex, yes that works. Any afternoon is good for me. Looking forward to meeting Tom.', now() - interval '300 minutes', null),
  ('eac7327c-8d2e-544c-8aaa-d2183f0ea160', '650d79a0-d943-54e9-a7d6-05b2d691511d', 'recruiter', 'Hi Isabella, your portfolio review with Maya is in the calendar. Let me know if you have any questions before then.', now() - interval '5800 minutes', now() - interval '4320 minutes'),
  ('eb40311b-25fe-5235-bfe3-f1b6884be9b6', '650d79a0-d943-54e9-a7d6-05b2d691511d', 'candidate', 'Quick question: will the portfolio review be with the whole design team, or just Maya?', now() - interval '4320 minutes', null),
  ('370d12b7-352e-56fd-8e50-1c825a2ae295', 'ab2b5fcd-3419-5f4f-9403-5cdeb8d34fdb', 'candidate', 'Thanks for the update! Excited for the next round.', now() - interval '4400 minutes', now() - interval '4370 minutes'),
  ('4c4634af-1929-5a80-9c46-3469e321312a', 'ab2b5fcd-3419-5f4f-9403-5cdeb8d34fdb', 'recruiter', 'Hi Priya, your product sense interview with Hannah is scheduled. Prep materials are waiting in your candidate portal.', now() - interval '2950 minutes', null),
  ('4dd5dac4-6d93-56a9-b695-5fe03ccde29a', 'fbde98a6-db26-535d-b40c-b159633f409c', 'recruiter', 'Hi Olivia, congratulations! Your offer is attached. Happy to walk through it together whenever suits you.', now() - interval '2880 minutes', null),
  ('52b3feef-e2aa-546a-93b8-5a648056d9b1', '510fb66b-d3df-5a45-9a31-d0690fbbe70e', 'recruiter', 'Hi Ethan, here''s the link to the infrastructure assessment. Take your time; most people spend about two hours on it.', now() - interval '4000 minutes', now() - interval '3000 minutes'),
  ('e7304cb1-5f20-5993-b8ab-3573a55c5a8b', '510fb66b-d3df-5a45-9a31-d0690fbbe70e', 'candidate', 'Just submitted the assessment. That was a fun one!', now() - interval '3000 minutes', now() - interval '2970 minutes'),
  ('428b64ef-b4f4-5dde-b82e-4b0799d10dec', '8322181d-603d-532c-b920-b79c1155bd7b', 'recruiter', 'Hi Hana, just checking you received the data science assessment. Let me know if you need more time.', now() - interval '6000 minutes', null),
  ('05e19712-ee75-52b8-b8f5-2be8f01f9ae7', 'c49cd191-43b1-5093-99ec-30dfaba6125c', 'candidate', 'Thanks Alex, I''ve had a look at the offer. Could we set up a call to go through the equity details?', now() - interval '6900 minutes', now() - interval '6870 minutes'),
  ('cd4cc8e4-14bc-53b4-ae5f-b51e0ab749e5', 'c49cd191-43b1-5093-99ec-30dfaba6125c', 'recruiter', 'Of course. I''ll book a call with Hannah and me so we can go through everything together.', now() - interval '6850 minutes', null),
  ('3b2f166b-5d1e-5103-9224-b2cfaf9ce288', '2740482e-fb75-59c2-bcea-0a3e28afe9e9', 'recruiter', 'Hi Leah, I lead recruiting for Encord''s product team. Your work on data platforms caught my eye. Would you be open to a quick chat about our Product Manager role?', now() - interval '12000 minutes', null),
  ('7f63de31-3af1-554d-9cb2-14b4b7e2e5f0', '57ad530b-ba59-5753-980c-0655b3f0ffe0', 'recruiter', 'Hi Rosa, thanks for the recruiter screen. Ian would like to meet you for a systems design interview for the Software Engineer role.', now() - interval '8800 minutes', now() - interval '8600 minutes'),
  ('87440329-5703-5a41-93ed-b8dbc84974af', '57ad530b-ba59-5753-980c-0655b3f0ffe0', 'candidate', 'Thanks Alex, happy to. Any day next week works for me.', now() - interval '8600 minutes', now() - interval '8570 minutes'),
  ('444393df-f07a-5e1f-9ce1-4770bab7fb74', '57ad530b-ba59-5753-980c-0655b3f0ffe0', 'recruiter', 'Your systems design interview with Ian is booked: 60 minutes on video, about scaling a data pipeline.', now() - interval '2000 minutes', null),
  ('da63d0de-e662-5ce8-b58a-45794c589cd7', '7b6a49e9-59bc-53f1-bf85-d1b3e3160201', 'recruiter', 'Hi Rosa, thanks for the recruiter screen. We''d love to move you forward to a technical interview for the Applied AI Engineer role with Lena and Tariq.', now() - interval '8800 minutes', now() - interval '8600 minutes'),
  ('2e2dc5c3-51cb-5273-96e6-34a854400b16', '7b6a49e9-59bc-53f1-bf85-d1b3e3160201', 'candidate', 'Thank you Mira, that sounds great. I''m looking forward to it.', now() - interval '8600 minutes', now() - interval '8570 minutes'),
  ('4bf39aae-b375-5257-b4d2-44e48dc26228', '7b6a49e9-59bc-53f1-bf85-d1b3e3160201', 'recruiter', 'Your technical interview is booked: 60 minutes on video, covering an LLM evaluation problem and a short system design discussion.', now() - interval '4300 minutes', null),
  ('53cfe11a-b048-587f-957a-fd0c9a340901', '6d6a41f3-12e8-5505-b163-142d4973ad66', 'recruiter', 'Hi Rosa, thanks for applying for the Platform Engineer role. Femke is reviewing your application this week, and I''ll be in touch about a technical screen.', now() - interval '2900 minutes', null),
  ('6470bdde-d82a-544d-bc56-b6fccffb87c4', '644b45ed-6e16-58fa-a9a3-c2648b32fc95', 'recruiter', 'Hi Sophia, thanks for applying for the Product Designer role. Your application is in screening now, and I''ll be in touch about next steps by the end of the week.', now() - interval '1000 minutes', null),
  ('d899d7b1-2a6d-5458-82d5-6525c8f92800', '66ce4a5a-eb68-5fac-9ef2-3d6737a82db4', 'recruiter', 'Hi Sophia, thank you for applying for the UX Designer role. We''d like to invite you to interview: a design exercise with Aiko, the hiring manager.', now() - interval '9000 minutes', now() - interval '8700 minutes'),
  ('2a9869d6-4c6a-58cc-a548-04e79d67ed2b', '66ce4a5a-eb68-5fac-9ef2-3d6737a82db4', 'candidate', 'Thank you Simone, I''d be glad to. Most afternoons work for me.', now() - interval '8700 minutes', now() - interval '8670 minutes'),
  ('090f19f0-5ea8-50b5-9749-da58e8576af9', '66ce4a5a-eb68-5fac-9ef2-3d6737a82db4', 'recruiter', 'Your design exercise with Aiko is booked: 60 minutes on video. Please confirm it in your portal when you can.', now() - interval '3500 minutes', null),
  ('6f4e52ff-5d0c-5528-a52a-6a986590c190', 'cba0f815-a6dc-5a9f-83fd-db8add16ff48', 'recruiter', 'Hi Daniel,
